    static void Check(bool v,string reason){if(!v)throw new Exception("Unified completion: "+reason);}
    static object Get(object o,string n){return o.GetType().GetField(n,F).GetValue(o);}static void Set(object o,string n,object v){o.GetType().GetField(n,F).SetValue(o,v);}static object Call(object o,string n,params object[] args){return o.GetType().GetMethod(n,F).Invoke(o,args);}
    static IEnumerable<T> Walk<T>(DependencyObject o)where T:DependencyObject{for(int n=0;n<VisualTreeHelper.GetChildrenCount(o);n++){var c=VisualTreeHelper.GetChild(o,n);if(c is T)yield return (T)c;foreach(var child in Walk<T>(c))yield return child;}}
