        string retainedFile=System.IO.Path.Combine(root,"Diagnostics/recent-failures.json");byte[] before=System.IO.File.ReadAllBytes(retainedFile);string log="2026-11-01T06:30:00.0000000Z stage=connected account=4 conversation=account:3 expected_peer=peer1 current_peer=peer1 candidate=relay source=server route=tls result=Ready\n2026-11-01T07:30:00.0000000Z stage=voice-failure account=4 conversation=account:3 expected_peer=peer1 current_peer=peer1 candidate=relay source=server route=webrtc result=Voice failed\n2026-11-01T07:31:00.0000000Z stage=retry account=4 conversation=account:3 expected_peer=peer1 current_peer=peer1 candidate=relay source=server route=tls result=Retrying";
        var logs=new LogsDiagnosticInput{Scope="fixture-profile:1",Profile="SAMPLE FIXTURE",RetentionAvailable=true,Log=log,Status="SAMPLE existing authenticated status",Failures=store.Failures().ToArray()};var projected=LogsDiagnosticProjection.Read(logs);Check(projected.Logs.Length==3&&projected.Failures.Length==2&&projected.Interruptions.Length==1,"existing log, failures and marker evidence");Check(projected.Interruptions[0].Details.Contains("NOT a confirmed crash")&&projected.Interruptions[0].Details.Contains("actual termination time not retained"),"no invented crash diagnosis/time");Check(LogsDiagnosticProjection.Filter(projected.Logs,"Voice","All","Voice").Length==1&&LogsDiagnosticProjection.Filter(projected.Logs,"","Warning","All").Length==1,"search, subsystem and severity filters");string safe=LogsDiagnosticProjection.Export(projected,"All metadata");Check(!safe.Contains("PRIVATE TOKEN")&&!safe.Contains("PRIVATE FROZEN MESSAGE BODY")&&safe.Contains("retained-failure-id")&&safe.Contains("2026-11-01T06:30:00.0000000Z"),"safe exports retain IDs/UTC without arbitrary bodies");Check(!LogsDiagnosticProjection.Export(projected,"Application logs").Contains("retained-failure-id"),"subsystem export isolation");Check(before.SequenceEqual(System.IO.File.ReadAllBytes(retainedFile)),"read-only retained data");Check(LogsDiagnosticProjection.Read(new LogsDiagnosticInput()).Interruptions.Length==0,"no fake crash reports");
